import networkx as nx

def calculate_sum_labels(G):
    degrees = dict(G.degree())
    s = 0
    for u, v in G.edges():
        s += abs(degrees[u] - degrees[v])
    return s

def get_partitions(n):
    if n == 0:
        yield []
        return
    for i in range(1, n + 1):
        for p in get_partitions(n - i):
            yield p + [i]

max_s = 0
for p in get_partitions(11):
    G = nx.complete_multipartite_graph(*p)
    max_s = max(max_s, calculate_sum_labels(G))

print(max_s)
